insert into products (slug, name, brand, model_code, category, subcategory, short_description, long_description, specs, key_specs, images, cost_price, cost_per_watt, module_watts, price_status, source_vat_inclusive, pricing_note, warranty_years, stock_status, stock_qty, requires_installation, compatible_with, datasheet_url, is_featured, is_published, source_supplier, source_list_date) values ('hanti-jfp-300', 'Hanti JFP-300 Direct Pressurised Flat-Plate Solar Water Heater, 300L', 'hanti', 'JFP-300', 'solar-water-heaters', 'flat-plate', 'Pressurised 300-litre flat-plate solar water heater for a household of five to seven people.', 'A direct pressurised flat-plate solar water heater with a 300-litre tank — sized for a household of five to seven people. Pressurised operation means strong, even flow at the shower rather than the weak trickle of gravity-fed systems, and flat-plate collectors are robust against hail and simple to maintain compared with vacuum tubes.
