insert into products (slug, name, brand, model_code, category, subcategory, short_description, long_description, specs, key_specs, images, cost_price, cost_per_watt, module_watts, price_status, source_vat_inclusive, pricing_note, warranty_years, stock_status, stock_qty, requires_installation, compatible_with, datasheet_url, is_featured, is_published, source_supplier, source_list_date) values ('jinko-solar-jkm615-bf', 'Jinko Solar Bifacial Monocrystalline PV Module, 615W', 'jinko-solar', 'JKM615-BF', 'solar-panels', 'bifacial', '615W bifacial monocrystalline module that also harvests light reflected onto its rear face.', 'The Tiger Neo 615W is a bifacial monocrystalline module: it generates from the front face like any panel, and adds output from light reflected onto its rear face — a real advantage over bright iron-sheet roofs and light-coloured ground. At 615W per module, an array reaches a target size with fewer panels, less rail and less labour than lower-wattage alternatives.
