insert into products (slug, name, brand, model_code, category, subcategory, short_description, long_description, specs, key_specs, images, cost_price, cost_per_watt, module_watts, price_status, source_vat_inclusive, pricing_note, warranty_years, stock_status, stock_qty, requires_installation, compatible_with, datasheet_url, is_featured, is_published, source_supplier, source_list_date) values ('solis-s6-eh1p5k-l', 'Solis S6-EH 1P LV 5kW Hybrid Inverter', 'solis', 'S6-EH1P5K-L', 'inverters', 'hybrid', '5 kW single phase hybrid inverter from the Solis S6 series.', 'The Solis S6-EH1P5K-L is a 5kW single-phase hybrid inverter for the 48V low-voltage battery class. It runs solar, battery and grid together: solar powers the house first, surplus charges the battery, and the grid fills any gap. When KPLC goes down, the backup port keeps essential circuits running from battery and solar.
